<?php $job=$operation['job']; $result=json_decode($job['result'],true); $payload=json_decode($job['payload'],true); ?>
<main id="deployment-content" data-status="<?= $e($job['status']) ?>" class="panel" data-operation="<?= $e($job['id']) ?>"><a href="/">← Back to your apps</a><section class="card"><div class="panel-heading"><h1><?= $e(ucfirst($job['kind'])) ?> progress</h1><span class="status" id="deployment-status" data-status="<?= $e($job['status']) ?>"><?= $e($job['status']) ?></span></div><dl class="deployment-meta"><dt>Operation</dt><dd><?= $e($job['id']) ?></dd><dt>Resource</dt><dd><?= $e($job['resource']) ?></dd><dt>Source</dt><dd><?= $e($payload['plan']['repository'] ?? $payload['app'] ?? $job['kind']) ?></dd><?php if (isset($payload['plan']['commit'])): ?><dt>Commit</dt><dd><?= $e($payload['plan']['commit']) ?></dd><?php endif ?></dl></section><p id="poll-message" role="status"></p><section class="card"><h2>Progress</h2><div class="log-container" id="logs-content"><?php foreach ($operation['steps'] as $step): ?><div class="log-line"><span class="log-time"><?= $e(date('H:i:s',(int)$step['at'])) ?></span><span class="log-level"><?= $e($step['step']) ?></span><?= $e($step['data']) ?></div><?php endforeach ?></div></section><section class="card"><h2>Result</h2><pre id="deployment-result"><?= $e(json_encode($result,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)) ?></pre><a id="next-deployment" class="wz-ok" <?= empty($result['deployment'])?'hidden':'' ?> href="/deployments?operation=<?= $e($result['deployment'] ?? '') ?>">Follow deployment →</a><p id="uncertain-help" <?= $job['status']==='uncertain'?'':'hidden' ?>>The outcome needs verification. Inspect the target before using reconciliation in Advanced. Do not start a duplicate deployment.</p></section></main>

<span hidden id="timeline-poll" mx-get="/deployments?operation=<?= $e(rawurlencode($job['id'])) ?>" mx-trigger="<?= in_array($job['status'], ['pending', 'running'], true) ? 'every 3s' : 'none' ?>" mx-target="#deployment-content" mx-select="#deployment-content" mx-swap="outerHTML" mx-after-swap="timelineRefresh" mx-on-error="#mx-error-trigger"></span>
